def recur(start: str, rule: str, count: int) -> list[str]:
    from datetime import date, timedelta
    from calendar import monthrange

    start_date = date.fromisoformat(start)
    parts = rule.split()
    frequency = parts[0]
    interval = int(parts[1])
    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                "FR": 4, "SA": 5, "SU": 6}
    result = []

    if frequency == "DAILY":
        current = start_date
        for i in range(count):
            result.append(current.isoformat())
            if i + 1 < count:
                current += timedelta(days=interval)
        return result

    if frequency == "WEEKLY":
        days = sorted(weekdays[day] for day in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        while len(result) < count:
            for day in days:
                current = week_start + timedelta(days=day)
                if current >= start_date:
                    result.append(current.isoformat())
                    if len(result) == count:
                        return result
            week_start += timedelta(weeks=interval)

    if frequency == "MONTHLY":
        month_index = start_date.year * 12 + start_date.month - 1
        while len(result) < count:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, last_day = monthrange(year, month)

            if len(parts) == 3:
                day = int(parts[2])
                if day == -1:
                    day = last_day
            else:
                occurrence = int(parts[2])
                weekday = weekdays[parts[3]]
                if occurrence == -1:
                    last_weekday = (first_weekday + last_day - 1) % 7
                    day = last_day - (last_weekday - weekday) % 7
                else:
                    day = 1 + (weekday - first_weekday) % 7
                    day += 7 * (occurrence - 1)

            if day <= last_day:
                current = date(year, month, day)
                if current >= start_date:
                    result.append(current.isoformat())
            month_index += interval
        return result

    month, day = map(int, parts[2].split("-"))
    year = start_date.year
    while len(result) < count:
        if day <= monthrange(year, month)[1]:
            current = date(year, month, day)
            if current >= start_date:
                result.append(current.isoformat())
        year += interval
    return result
